          "passive": true,
          "description": "Every Quartz in the United Frontier starts out as a Clear Quartz, colorless and unshaped. As she grows and settles into what she wants to become, her coloration shifts to match the Quartz type suited to that path. When the shift completes, she gains that type's stat modifiers and abilities. A shift never adds stats overall: any power she gains is paid for with stats, so every Quartz stays on equal footing. A Clear Quartz who hasn't found her path keeps her base stats.",
