          "moves": [],
          "sourceText": "`Enhanced Senses` - Era 1B gems have advantage on perception checks. While an Era 1B gem is conscious, their party can't be ambushed.\n`Weak Essence Buster [1 SP]` - A lighter version of Essence Buster, dealing 1d6 + MAG damage, or 2d4 + MAG against Diamonds and Cubic Zirconias.\n\n``Era 1B Gems emerged during the Age of the Judge, the era in which Epsilon Blue Diamond joined Theta Gold in the creation process. These gems were the first shaped by a proper dual Diamond influence. As a result, Era 1B Gems are sharper, quicker, and more perceptive than their Era 1A predecessors, capable of reading situations, patterns, and the emotions of others with uncanny accuracy. Their forms are lighter and less rigid due to the fading presence of Alpha Black's essence, but their minds lean much more toward diplomacy, analysis, and high level reasoning. Many Era 1B Gems became the diplomats, advisors, and administrative backbone of later Homeworld society.``"
