      "profileMarkdown": "# PERFECT CUTS\n> Perfect cuts are gems that emerge at the highest quality possible for their gem type; no defects whatsoever and an above-average build or skill. They tend to be slightly larger than their average-cut counterparts; these gems are highly praised within the empire.\n>\n> An example of a Perfect Cut would be a Perfect Cut Sapphire, who is larger than the typical Sapphire and bears Perfect Clairvoyance instead of the regular kind. How do they see the future? Well, they would see it more precisely than the typical Sapphire. The same rule may be applied to other Perfect Cut Gems.\n\n**``STAT MODIFIERS``**\n_``HP:``_ +2\n_``ATK:``_ +1\n_``DEF:``_ 0\n_``SPD:``_ 0\n_``INT:``_ 0\n_``MAG:``_ +1\n_``Special:``_\n`Enhanced Signature` - The gem-type's signature ability goes up one Rating step, for example from Base to Enhanced. For a Sapphire, that means Enhanced Clairvoyance."
